mapper.insert:
/* 
 * isry.couns.constt.bbsout.mapper.BbsoutListMapper.insertBbsout : 아웃리치 게시글등록 
 * 2023.04.25 수정 : 불필요한 컬럼 삭제 / 필요한 컬럼 추가 - Jeong.Won.Je
 */

       SELECT  AYE100_SQ01.CURRVAL
       FROM    DUAL

    INSERT  
	INTO    
            AYE100 
	(
	        BBSCTT_ESNTAL_NO            /* 게시글고유번호 */
	    ,   BBSCTT_TYPE_SE_CD           /* 게시글유형구분코드 */
        ,   BBSCTT_TTL_NM               /* 게시글 제목 */
		,   WRTR_NM_ENCPT               /* 작성자명 */
        ,   HPGE_URL_ADDR               /* 홈페이지URL주소 */
		,   OUTRC_DSCSN_MTHD_SE_CD      /* 아웃리치상담방법 */
		,   SNS_SE_CD                   /* SNS구분코드 */
		,   BBSCTT_CN                   /* 게시글내용 */
        ,   SXDC_SE_CD                  /* 성별 */
		,   ACBG_SE_CD                  /* 학력구분코드 */
        ,   GRADE_SE_CD                 /* 학년구분코드 */
        ,   GRDTN_STTS_SE_CD            /* 졸업상태구분코드 */
        ,   REAL_CONSTT_SE_CD           /* 실제상담자구분코드 */
        ,   REAL_CONSTT_ETC_CN          /* 실제상담자기타내용 */
        ,   YNGBGS_SE_NO                /* 청소년구분번호 */
		,   PROBM_STTS_LCLAS_SE_CD      /* 문제상태대분류 */
		,   PROBM_STTS_MLSFC_SE_CD      /* 문제상태중분류 */
		,   PROBM_STTS_SCLAS_SE_CD      /* 문제상태소분류 */
		,   PROBM_CAS_LCLAS_SE_CD       /* 문제원인대분류 */
		,   PROBM_CAS_SCLAS_SE_CD       /* 문제원인소분류 */
		,   ETC_CN                      /* 기타내용 */
		,   LINK_PRCS_SE_CN             /* 연계처리구분내용 */
        ,   RCPT_RQST_COURS_SE_CD       /* 접수의뢰경로구분코드 */
        ,   LINK_INST_NM                /* 연계기관명 */
        ,   FRST_RGTR_ID                /* 최초등록아이디 */
		,	FRST_REG_DT                 /* 최초등록일자 */
		,	LAST_MDFR_ID                /* 최종수정아이디 */
		,	LAST_MDFCN_DT               /* 최종수정일자 */
	)
	VALUES
	(
	        AYE100_SQ01.NEXTVAL
	    ,   #{BBSCTT_TYPE_SE_CD}
	    ,   #{BBSCTT_TTL_NM}
	    ,   C##RG.ENC_B64(#{WRTR_NM_ENCPT})
	    ,   #{HPGE_URL_ADDR}
	    ,   #{OUTRC_DSCSN_MTHD_SE_CD}
	    ,   #{SNS_SE_CD}
	    ,   #{BBSCTT_CN}
	    ,   #{SXDC_SE_CD}      
	    ,   #{ACBG_SE_CD}
	    ,   #{GRADE_SE_CD}
	    ,   #{GRDTN_STTS_SE_CD}
        ,   #{REAL_CONSTT_SE_CD}
        ,   #{REAL_CONSTT_ETC_CN}
        ,   #{YNGBGS_SE_NO}
        ,   #{PROBM_STTS_LCLAS_SE_CD}
        ,   #{PROBM_STTS_MLSFC_SE_CD}
        ,   #{PROBM_STTS_SCLAS_SE_CD}
        ,   #{PROBM_CAS_LCLAS_SE_CD}
        ,   #{PROBM_CAS_SCLAS_SE_CD}
	    ,   #{ETC_CN}
	    ,   #{LINK_PRCS_SE_CN}
        ,   #{RCPT_RQST_COURS_SE_CD}
        ,   #{LINK_INST_NM}
	    ,   #{FRST_RGTR_ID}
	    ,   SYSDATE
	    ,   #{LAST_MDFR_ID}
	    ,   SYSDATE 
	)

mapper.update:
/* 
 * isry.couns.constt.bbsout.mapper.BbsoutListMapper.deleteBbsout : 아웃리치 게시글삭제 
 */
	UPDATE  
            AYE100 
	SET
            DEL_YN                 =       'Y'
        ,   LAST_MDFCN_DT          =       SYSDATE      
        ,   LAST_MDFR_ID           =       #{LAST_MDFR_ID}    
    WHERE   1=1
    AND     BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND     BBSCTT_TYPE_SE_CD      =       #{BBSCTT_TYPE_SE_CD}

UPDATE  /* isry.couns.constt.bbsout.mapper.BbsoutListMapper.insertCrisis : 아웃리치 위기유형등록 */
        AYE100  
SET
        CRISIS_TYPE_SE_CD      =       #{CRISIS_TYPE_SE_CD} 
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD      =       '35'                   /*  게시판유형구분코드  */

mapper.insert:
MERGE /* isry.couns.constt.bbsout.mapper.BbsoutListMapper.insertCrisisBoard : 아웃리치 위기유형저장 */ INTO AYA110 AA USING ( SELECT #{BBSCTT_ESNTAL_NO} AS BBSCTT_ESNTAL_NO , '35' AS BBSCTT_TYPE_SE_CD , #{CRISIS_TYPE_SE_CD} AS CRISIS_TYPE_SE_CD , #{FRST_RGTR_ID} AS FRST_RGTR_ID , #{LAST_MDFR_ID} AS LAST_MDFR_ID FROM DUAL ) BB ON ( AA.BBSCTT_ESNTAL_NO = BB.BBSCTT_ESNTAL_NO AND AA.BBSCTT_TYPE_SE_CD = BB.BBSCTT_TYPE_SE_CD ) WHEN MATCHED THEN UPDATE SET CRISIS_TYPE_SE_CD = BB.CRISIS_TYPE_SE_CD , LAST_MDFR_ID = BB.LAST_MDFR_ID , LAST_MDFCN_DT = SYSDATE
WHEN NOT MATCHED THEN INSERT ( INDEX_SN /* 색인일련번호 */ , BBSCTT_ESNTAL_NO /* 게시글고유번호 */ , BBSCTT_TYPE_SE_CD /* 게시글구분코드 */ , CRISIS_TYPE_SE_CD /* 위기유형구분 */ , FRST_RGTR_ID , FRST_REG_DT , LAST_MDFR_ID , LAST_MDFCN_DT
) VALUES ( ( SELECT NVL(MAX(INDEX_SN),0) +1 FROM AYA110 ) , BB.BBSCTT_ESNTAL_NO , BB.BBSCTT_TYPE_SE_CD , BB.CRISIS_TYPE_SE_CD , BB.FRST_RGTR_ID , SYSDATE , BB.LAST_MDFR_ID , SYSDATE )

MERGE /* isry.couns.constt.bbsout.mapper.BbsoutListMapper.insertCrisisPerson : 아웃리치 위기유형저장 */ INTO AYA120 AA USING ( SELECT #{BBSCTT_ESNTAL_NO} AS BBSCTT_ESNTAL_NO , '35' AS BBSCTT_TYPE_SE_CD , #{CRISIS_TYPE_SE_CD} AS CRISIS_TYPE_SE_CD , #{CLIENA_ID} AS CLIENA_ID , #{FRST_RGTR_ID} AS FRST_RGTR_ID , #{LAST_MDFR_ID} AS LAST_MDFR_ID FROM DUAL ) BB ON ( AA.BBSCTT_ESNTAL_NO = BB.BBSCTT_ESNTAL_NO AND AA.BBSCTT_TYPE_SE_CD = BB.BBSCTT_TYPE_SE_CD ) WHEN MATCHED THEN UPDATE SET CRISIS_TYPE_SE_CD = BB.CRISIS_TYPE_SE_CD , CLIENA_ID = BB.CLIENA_ID , LAST_MDFR_ID = BB.LAST_MDFR_ID , LAST_MDFCN_DT = SYSDATE
WHEN NOT MATCHED THEN INSERT ( INDEX_SN /* 색인일련번호 */ , BBSCTT_ESNTAL_NO /* 게시글고유번호 */ , BBSCTT_TYPE_SE_CD /* 게시글구분코드 */ , CLIENA_ID , CRISIS_TYPE_SE_CD /* 위기유형구분 */ , FRST_RGTR_ID , FRST_REG_DT , LAST_MDFR_ID , LAST_MDFCN_DT
) VALUES ( ( SELECT NVL(MAX(INDEX_SN),0) +1 FROM AYA120 ) , BB.BBSCTT_ESNTAL_NO , BB.BBSCTT_TYPE_SE_CD , BB.CLIENA_ID , BB.CRISIS_TYPE_SE_CD , BB.FRST_RGTR_ID , SYSDATE , BB.LAST_MDFR_ID , SYSDATE )

mapper.update:
UPDATE  /* isry.couns.constt.medscsnntabrd.mapper.BbsoutListMapper.updateCrisisBoard : 아웃리치 위기유형등록 */
        AYA110  
SET
        CRISIS_TYPE_SE_CD       =       #{CRISIS_TYPE_SE_CD} 
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD      =       '35'                   /*  게시판유형구분코드  */

UPDATE  /* isry.couns.constt.medscsnntabrd.mapper.BbsoutListMapper.updateCrisisPerson : 아웃리치 위기유형등록 */
        AYA120  
SET
        CRISIS_TYPE_SE_CD       =       #{CRISIS_TYPE_SE_CD} 
    ,   CLIENA_ID               =       #{CLIENA_ID}
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD      =       '35'                   /*  게시판유형구분코드  */
